// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IVerifier {
    function verifyProof(
        uint[2] calldata _pA,
        uint[2][2] calldata _pB,
        uint[2] calldata _pC,
        uint[6] calldata _pubSignals
    ) external view returns (bool);
}

contract PrivacyKYC {
    IVerifier public immutable verifier;

    mapping(bytes32 => bool) public verifiedCommitments;
    mapping(bytes32 => uint256) public commitmentExpiry;
    mapping(address => bytes32) public userCommitment;

    uint256 public constant KYC_VALIDITY = 365 days;

    event KYCVerified(address indexed user, bytes32 indexed commitment, uint256 expiry);
    event KYCRevoked(address indexed user, bytes32 indexed commitment);

    constructor(address _verifier) {
        verifier = IVerifier(_verifier);
    }

    function verifyAgeProof(
        uint256[2] calldata a,
        uint256[2][2] calldata b,
        uint256[2] calldata c,
        uint256[6] calldata input
    ) external returns (bool) {
        require(input[4] == 18, "Age threshold must be 18");
        require(
            verifier.verifyProof(a, b, c, input),
            "Invalid ZK proof"
        );

        bytes32 commitment = bytes32(input[5]);
        verifiedCommitments[commitment] = true;
        commitmentExpiry[commitment] = block.timestamp + KYC_VALIDITY;
        userCommitment[msg.sender] = commitment;

        emit KYCVerified(msg.sender, commitment, block.timestamp + KYC_VALIDITY);
        return true;
    }

    function isKYCVerified(address user) external view returns (bool) {
        bytes32 commitment = userCommitment[user];
        if (commitment == bytes32(0)) return false;
        if (!verifiedCommitments[commitment]) return false;
        return block.timestamp <= commitmentExpiry[commitment];
    }

    function getKYCDetails(address user) external view returns (
        bool hasAge,
        bool hasResidency,
        uint256 expiry
    ) {
        bytes32 commitment = userCommitment[user];
        if (commitment == bytes32(0)) return (false, false, 0);
        bool active = verifiedCommitments[commitment] &&
                      block.timestamp <= commitmentExpiry[commitment];
        return (active, false, commitmentExpiry[commitment]);
    }

    function revokeMyKYC() external {
        bytes32 commitment = userCommitment[msg.sender];
        require(commitment != bytes32(0), "No KYC found");
        verifiedCommitments[commitment] = false;
        delete userCommitment[msg.sender];
        emit KYCRevoked(msg.sender, commitment);
    }
}

